// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import { Initializable } from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import { PausableUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import { UUPSUpgradeable } from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import { ReentrancyGuardUpgradeable } from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import { AccessControlUpgradeable } from "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { SafeERC20 } from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import { IFactory } from "./interfaces/IFactory.sol";
import { IPosition } from "./interfaces/IPosition.sol";
import { ILPRouter } from "./interfaces/ILPRouter.sol";
import { IWrappedNative } from "./interfaces/IWrappedNative.sol";
import { IPaboxoEmitter } from "./interfaces/IPaboxoEmitter.sol";
import { IRouterClient } from "./interfaces/IRouterClient.sol";
import { Client } from "./libraries/Client.sol";
import { LendingPoolHook } from "./lib/LendingPoolHook.sol";
import { BorrowParams, RepayParams } from "./lib/LendingPoolHook.sol";
import { SwapHook } from "./lib/SwapHook.sol";

/**
 * ______  ___  ______  _______   _______
 * | ___ \/ _ \ | ___ \|  _  \ \ / /  _  |
 * | |_/ / /_\ \| |_/ /| | | |\ V /| | | |
 * |  __/|  _  || ___ \| | | |/   \| | | |
 * | |   | | | || |_/ /\ \_/ / /^\ \ \_/ /
 * \_|   \_| |_/\____/  \___/\/   \/\___/
 *
 * @title LendingPool
 * @notice Core lending pool contract for supplying liquidity, borrowing, and managing collateral
 * @dev Implements lending pool functionality with position-based collateral management. The
 *      cross-chain borrow leg is reworked from LayerZero (OFT) to Chainlink CCIP (see Phase 7.1)
 *      and stays guarded-off for the single-chain HashKey MVP.
 */
contract LendingPool is
    Initializable,
    PausableUpgradeable,
    UUPSUpgradeable,
    ReentrancyGuardUpgradeable,
    AccessControlUpgradeable,
    LendingPoolHook,
    SwapHook
{
    using SafeERC20 for IERC20;

    /// @notice Address of the lending pool router contract
    address public router;

    /// @notice Address of the creator of the lending pool
    address public creator;

    /// @dev Track if we're in a withdrawal operation to avoid auto-wrapping
    bool private _withdrawing;

    /// @notice Credit delegation: owner => delegate => borrow amount the delegate may draw against the
    ///         owner's collateral. The debt is booked to the owner; the borrowed funds go to the delegate.
    mapping(address => mapping(address => uint256)) public borrowDelegation;

    /// @notice Withdraw delegation: owner => delegate => may the delegate trigger withdrawals of the owner's
    ///         collateral/liquidity. Withdrawn funds always go to the OWNER, so a delegate can trigger but not steal.
    mapping(address => mapping(address => bool)) public withdrawDelegation;

    /// @notice Rebalance delegation: owner => delegate => may the delegate rotate the owner's collateral
    ///         (swap one collateral token for another inside the owner's position). Health is re-checked after
    ///         the swap, so a delegate (e.g. an AI keeper) can protect a position but cannot make it unhealthy or
    ///         divert funds — the swapped output stays in the owner's position.
    /// @dev Appended after withdrawDelegation to preserve the UUPS storage layout of already-deployed pools.
    mapping(address => mapping(address => bool)) public rebalanceDelegation;

    /// @notice 1e18 fixed-point one (WAD) — the scale DODO V2 uses for its fee/price math (`DecimalMath.ONE`).
    uint256 private constant WAD = 1e18;

    /// @notice Extra input provisioned on an on-behalf swap-to-repay so the DEX fee + slippage still leaves at
    ///         least the debt. A spot-sized swap returns `debt * (1 - fee)` on a real fee-charging DEX (DODO's
    ///         `_LP_FEE_RATE_` is `3e15` = 0.3%), which would trip the `minOut` floor. `1e16` = 1% covers the
    ///         fee plus slippage headroom; the surplus goes to the pool (never shorted). Mirrors
    ///         `Position.SWAP_COST_BUFFER` (the from-position repay path). Constant → storage-layout safe.
    uint256 private constant SWAP_COST_BUFFER = 1e16;

    // =============================================================
    //                           CONSTRUCTOR
    // =============================================================

    /// @notice Initializes the LendingPool contract with a router address
    /// @dev Sets up Ownable with deployer as owner and configures the router
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the upgradeable contract with default settings and roles
    /// @dev This function replaces the constructor for upgradeable contracts.
    ///      Sets up default scaled percentage to 1e18 (100% in basis points)
    function initialize(address _router, address _creator) public initializer {
        __AccessControl_init();
        __Pausable_init();
        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();

        router = _router;
        creator = _creator;

        address owner = _ownerFactory();

        _grantRole(DEFAULT_ADMIN_ROLE, owner);
        _grantRole(OWNER_ROLE, owner);
        _grantRole(UPGRADER_ROLE, owner);
    }

    /**
     * @notice Modifier to ensure user has a position contract
     * @param _user User address to check
     * @dev Creates position if it doesn't exist
     */
    modifier positionRequired(address _user) {
        _positionRequired(_user);
        _;
    }

    /**
     * @notice Modifier for access control checks
     * @param _user User address to validate
     * @dev Allows operators or the user themselves
     */
    modifier accessControl(address _user) {
        _accessControl(_user);
        _;
    }

    /**
     * @notice Restricts a withdrawal to `_onBehalf` themselves or an address they authorized as a withdraw delegate
     * @param _onBehalf The owner whose collateral/liquidity is being withdrawn (funds always return to them)
     * @dev Reverts WithdrawNotDelegated otherwise. Borrow uses its own amount-based delegation inline, since it
     *      consumes the allowance (a state change that does not belong in a modifier).
     */
    modifier onlyOwnerOrWithdrawDelegate(address _onBehalf) {
        _authorizeOnBehalf(_onBehalf);
        _;
    }

    /**
     * @notice Modifier to ensure amount is not zero
     * @param _amount Amount to check
     */
    modifier nonZeroAmount(uint256 _amount) {
        _nonZeroAmount(_amount);
        _;
    }

    // =============================================================
    //                      PAUSABLE FUNCTIONS
    // =============================================================

    /**
     * @notice Pauses all pausable functions in the contract
     * @dev Can only be called by accounts with OWNER_ROLE
     */
    function pause() external onlyRole(OWNER_ROLE) {
        _pause();
    }

    /**
     * @notice Unpauses all pausable functions in the contract
     * @dev Can only be called by accounts with OWNER_ROLE
     */
    function unpause() external onlyRole(OWNER_ROLE) {
        _unpause();
    }

    // =============================================================
    //                      EXTERNAL FUNCTIONS
    // =============================================================

    /**
     * @notice Supply liquidity to the lending pool by depositing borrow tokens.
     * @dev Users receive shares proportional to their deposit. Shares represent ownership in the pool. Accrues interest before deposit.
     * @param _user The address of the user to supply liquidity.
     * @param _amount The amount of borrow tokens to supply as liquidity.
     * @custom:emits SupplyLiquidity when liquidity is supplied.
     */
    /// @dev On-behalf & permissionless: funds are pulled from the caller (`_msgSender()`) while the supply
    ///      shares are credited to `_user`. Anyone may supply on behalf of any beneficiary — it can only
    ///      increase `_user`'s balance, so no authorization gate is required.
    function supplyLiquidity(address _user, uint256 _amount) public payable whenNotPaused nonReentrant {
        uint256 shares = _supplyLiquidity(_amount, _user);
        _supplyLiquidityTransfer(_amount);
        emit SupplyLiquidity(_user, _amount, shares);
    }

    /**
     * @notice Redeem `_onBehalf`'s supply shares for underlying tokens. The tokens always go to `_onBehalf`.
     * @dev Accrues interest before withdrawal. Access is restricted to `_onBehalf` themselves or an address they
     *      authorized via {approveWithdrawDelegation} — a delegate can trigger the withdrawal but cannot divert it
     *      (funds go to the owner). Pass your own address as `_onBehalf` to withdraw your own liquidity.
     * @param _shares The number of supply shares to redeem for underlying tokens.
     * @param _onBehalf The owner whose shares are redeemed and who receives the underlying tokens.
     * @custom:throws WithdrawNotDelegated if the caller is neither `_onBehalf` nor an authorized delegate.
     * @custom:emits WithdrawLiquidity when liquidity is withdrawn.
     */
    function withdrawLiquidity(uint256 _shares, address _onBehalf) public payable whenNotPaused nonReentrant onlyOwnerOrWithdrawDelegate(_onBehalf) {
        _doWithdrawLiquidity(_shares, _onBehalf);
    }

    /**
     * @notice Supply collateral tokens to the user's position in the lending pool.
     * @dev Transfers collateral tokens from user to their Position contract. Accrues interest before deposit.
     * @param _user The address of the user to supply collateral.
     * @param _amount The amount of collateral tokens to supply.
     * @custom:throws ZeroAmount if amount is 0.
     * @custom:emits SupplyCollateral when collateral is supplied.
     */
    function supplyCollateral(address _user, uint256 _amount)
        public
        payable
        whenNotPaused
        nonReentrant
        positionRequired(_user)
        nonZeroAmount(_amount)
    {
        // On-behalf & permissionless: funds come from the caller, collateral is credited to `_user`'s position.
        // Supplying collateral can only make `_user`'s position healthier, so no authorization gate is required.
        _accrueInterest();
        _supplyCollateralTransfer(_user, _amount);
        emit SupplyCollateral(_addressPositions(_user), _user, _amount);
    }

    /**
     * @notice Withdraw supplied collateral from the user's position.
     * @dev Transfers collateral tokens from Position contract back to user. Accrues interest before withdrawal.
     * @param _amount The amount of collateral tokens to withdraw.
     * @custom:throws ZeroAmount if amount is 0.
     * @custom:throws InsufficientCollateral if user has insufficient collateral balance.
     */
    function withdrawCollateral(
        uint256 _amount,
        address _onBehalf
    )
        public
        whenNotPaused
        nonReentrant
        positionRequired(_onBehalf)
        nonZeroAmount(_amount)
        onlyOwnerOrWithdrawDelegate(_onBehalf)
    {
        _doWithdrawCollateral(_amount, _onBehalf);
    }

    /**
     * @notice Borrow against `_onBehalf`'s collateral. Routes by `params.chainId`: equal to the current chain =
     *         a same-chain borrow (funds to the caller); any other chain = a cross-chain borrow bridged via CCIP.
     * @dev Accrues interest, checks liquidity and `_onBehalf`'s health (in the router). If the caller is not
     *      `_onBehalf` it acts as a credit-delegate: it must hold a sufficient allowance granted by `_onBehalf`
     *      via {approveBorrowDelegation}, which is consumed by `params.amount`. The debt is always booked to
     *      `_onBehalf`. Pass your own address as `_onBehalf` to borrow for yourself. The cross-chain leg stays
     *      guarded-off (reverts CrossChainDisabled) until the CCIP router + destination selector are configured.
     * @param params Borrow params: `amount`, `chainId` (current chain = local; other = CCIP destination), `destGasLimit`.
     * @param _onBehalf The collateral owner the debt is booked to (and whose delegation is consumed if delegated).
     * @custom:throws InsufficientBorrowDelegation if the caller is a delegate without enough allowance.
     * @custom:throws InsufficientLiquidity if the protocol lacks liquidity.
     * @custom:throws CrossChainDisabled if a cross-chain borrow is requested before the CCIP leg is enabled.
     * @custom:emits BorrowDebt (same-chain) or BorrowDebtCrossChain.
     */
    function borrowDebt(BorrowParams calldata params, address _onBehalf) public payable nonReentrant whenNotPaused {
        // Delegated borrow (caller != owner) consumes the owner's credit-delegation allowance; self-borrow is free.
        if (_msgSender() != _onBehalf) {
            uint256 allowance = borrowDelegation[_onBehalf][_msgSender()];
            if (allowance < params.amount) revert InsufficientBorrowDelegation();
            borrowDelegation[_onBehalf][_msgSender()] = allowance - params.amount;
        }
        (uint256 creatorFee, uint256 protocolFee, uint256 userAmount, uint256 shares) = _borrowDebt(params.amount, _onBehalf);
        if (params.chainId == block.chainid) {
            // Same-chain borrow: deliver the funds to the caller.
            _borrowDebtTransfer(userAmount, creatorFee, protocolFee);
            emit BorrowDebt(_onBehalf, protocolFee, userAmount, shares, params.amount);
        } else {
            // Cross-chain borrow via Chainlink CCIP — guarded-off (reverts CrossChainDisabled) until the router
            // and destination selector are configured.
            _borrowDebtCrosschain(userAmount, creatorFee, protocolFee, params);
            emit BorrowDebtCrossChain(_onBehalf, protocolFee, userAmount, shares, params);
        }
    }

    /**
     * @notice Swaps tokens within a user's position
     * @param params Struct containing:
     *        - tokenIn: Address of the input token
     *        - tokenOut: Address of the output token
     *        - amountIn: Amount of input tokens
     *        - amountOutMinimum: Minimum output amount (slippage protection)
     * @return amountOut Amount of output tokens received
     * @dev Oracle validation done in Position contract
     */
    function swapTokenByPosition(SwapParams calldata params)
        public
        whenNotPaused
        nonReentrant
        positionRequired(_msgSender())
        accessControl(_msgSender())
        returns (uint256 amountOut)
    {
        amountOut = IPosition(_addressPositions(_msgSender())).swapTokenByPosition(params);
        emit SwapTokenByPosition(_msgSender(), params.tokenIn, params.tokenOut, params.amountIn, amountOut);
    }

    /**
     * @notice Rotate a user's collateral inside their position (e.g. volatile -> stable) to protect it from
     *         liquidation. Callable by the position owner, a protocol operator, or an address the owner
     *         authorized via {approveRebalanceDelegation} (e.g. an AI keeper). The Position re-checks health
     *         after the swap, so this can never make the position unhealthy, and the swapped output stays in
     *         the owner's position — no funds leave.
     * @param _user The position owner whose collateral is rotated.
     * @param params Swap parameters (tokenIn/tokenOut/amountIn/amountOutMinimum/fee).
     * @return amountOut Amount of tokenOut received into the position.
     * @custom:emits PositionRebalanced.
     */
    function rebalancePosition(
        address _user,
        SwapParams calldata params
    )
        public
        whenNotPaused
        nonReentrant
        positionRequired(_user)
        returns (uint256 amountOut)
    {
        if (_msgSender() != _user && !IFactory(_factory()).operator(_msgSender()) && !rebalanceDelegation[_user][_msgSender()]) {
            revert RebalanceNotDelegated();
        }
        amountOut = IPosition(_addressPositions(_user)).swapTokenByPosition(params);
        emit PositionRebalanced(_user, params.tokenIn, params.tokenOut, params.amountIn, amountOut);
    }

    /**
     * @notice Repays debt using a selected token. Can swap collateral to borrow token for repayment.
     * @dev Allows flexible repayment using any configured token. Checks health after repayment.
     * @param params Struct containing:
     *        - user: The user whose debt is being repaid
     *        - token: The token to use for repayment (can be borrow token or collateral token)
     *        - shares: The amount of shares to repay
     *        - amountOutMinimum: The slippage tolerance in basis points (e.g., 500 = 5%)
     *        - fromPosition: Whether to use tokens from the position contract (true) or from the user's wallet (false)
     * @custom:throws ZeroAmount if shares is 0.
     * @custom:emits RepayByPosition when repayment is successful.
     */
    /// @dev On-behalf: repaying `params.user`'s debt with the caller's own funds (direct or swap-from-wallet)
    ///      is permissionless — it can only reduce `params.user`'s liability. Spending `params.user`'s OWN
    ///      position collateral (`fromPosition`) stays authorization-gated inside {_repayWithSelectedTokenTransfer}.
    function repayWithSelectedToken(RepayParams calldata params) public payable whenNotPaused nonReentrant positionRequired(params.user) {
        uint256 borrowAmount = _repayWithSelectedToken(params.shares, params.user);
        _repayWithSelectedTokenTransfer(params, borrowAmount);
        emit RepayByPosition(params.user, borrowAmount, params.shares);
    }

    /**
     * @notice Liquidates an unhealthy borrower's position
     * @param _borrower The address of the borrower to liquidate
     * @dev Transfers borrow token from liquidator, sends collateral bonus to liquidator
     */
    function liquidation(address _borrower) public payable nonReentrant {
        (uint256 userBorrowAssets, uint256 liquidationBonus, address userPosition) = ILPRouter(router).liquidation(_borrower);

        _isNativeTransferFrom(_msgSender(), _borrowToken(), userBorrowAssets);
        IPosition(userPosition).liquidation(_msgSender(), liquidationBonus);

        emit Liquidation(_borrower, _borrowToken(), _collateralToken(), userBorrowAssets, liquidationBonus);
    }

    // =============================================================
    //                    CREDIT / WITHDRAW DELEGATION
    // =============================================================

    /**
     * @notice Grant `delegate` a credit-delegation allowance to borrow up to `amount` against the caller's
     *         collateral (funds go to the delegate; the debt stays with the caller). Pass 0 to revoke.
     * @param delegate Address permitted to draw against the caller's collateral.
     * @param amount New delegated borrow allowance.
     * @custom:emits BorrowDelegationApproved.
     */
    function approveBorrowDelegation(address delegate, uint256 amount) external {
        borrowDelegation[_msgSender()][delegate] = amount;
        emit BorrowDelegationApproved(_msgSender(), delegate, amount);
    }

    /**
     * @notice Authorize (or revoke) `delegate` to trigger withdrawals of the caller's collateral/liquidity.
     *         Withdrawn funds are always sent to the caller (the owner), so this cannot be used to steal.
     * @param delegate Address permitted to trigger the caller's withdrawals.
     * @param allowed Whether the delegation is enabled.
     * @custom:emits WithdrawDelegationApproved.
     */
    function approveWithdrawDelegation(address delegate, bool allowed) external {
        withdrawDelegation[_msgSender()][delegate] = allowed;
        emit WithdrawDelegationApproved(_msgSender(), delegate, allowed);
    }

    /**
     * @notice Opt in (or out) an address to rebalance the caller's collateral via {rebalancePosition}
     *         (e.g. authorize an AI keeper to rotate volatile collateral into a stable one before a drop).
     *         The delegate can only swap inside the caller's position; health is re-checked, funds never leave.
     * @param delegate Address permitted to rebalance the caller's position.
     * @param allowed Whether the delegation is enabled.
     * @custom:emits RebalanceDelegationApproved.
     */
    function approveRebalanceDelegation(address delegate, bool allowed) external {
        rebalanceDelegation[_msgSender()][delegate] = allowed;
        emit RebalanceDelegationApproved(_msgSender(), delegate, allowed);
    }

    // =============================================================
    //                    INTERNAL HELPER FUNCTIONS
    // =============================================================

    /**
     * @notice Shared liquidity-withdraw path: redeems `_owner`'s shares and returns the underlying to `_owner`.
     * @param _shares Shares to redeem.
     * @param _owner Owner whose shares are redeemed and who receives the underlying tokens.
     */
    function _doWithdrawLiquidity(uint256 _shares, address _owner) internal {
        uint256 amount = _withdrawLiquidity(_shares, _owner);
        _withdrawLiquidityTransfer(amount, _owner);
        emit WithdrawLiquidity(_owner, amount, _shares);
    }

    /**
     * @notice Shared collateral-withdraw path: returns `_owner`'s collateral to `_owner` and re-checks health.
     * @param _amount Amount of collateral to withdraw.
     * @param _owner Owner whose collateral is withdrawn and who receives it.
     */
    function _doWithdrawCollateral(uint256 _amount, address _owner) internal {
        _accrueInterest();
        _withdrawCollateralTransfer(_amount, _owner);
        emit WithdrawCollateral(_owner, _amount);
    }

    /**
     * @notice Creates a new Position contract for the caller if one does not already exist.
     * @dev Each user can have only one Position contract. The Position contract manages collateral and borrowed assets for the user.
     * @param _user The address of the user to create a position.
     * @custom:throws PositionAlreadyCreated if the caller already has a Position contract.
     * @custom:emits CreatePosition when a new Position is created.
     */
    function _createPosition(address _user) internal {
        address position = _addressPositions(_user);
        if (position != address(0)) revert PositionAlreadyCreated(position);
        ILPRouter(router).createPosition(_user);
        IPaboxoEmitter(_paboxoEmitter()).positionCreated(address(this), router, _user, position);
    }

    /**
     * @notice Internal function to calculate and apply accrued interest to the protocol.
     * @dev Uses dynamic interest rate model based on utilization. Updates total supply and borrow assets and last accrued timestamp.
     */
    function _accrueInterest() internal {
        ILPRouter(router).accrueInterest();
    }

    // =============================================================
    //                      ROUTER DELEGATIONS
    // =============================================================

    /**
     * @notice Gets the borrow token address from router
     * @return Address of the borrow token
     */
    function _borrowToken() internal view returns (address) {
        return ILPRouter(router).borrowToken();
    }

    /**
     * @notice Gets the collateral token address from router
     * @return Address of the collateral token
     */
    function _collateralToken() internal view returns (address) {
        return ILPRouter(router).collateralToken();
    }

    /**
     * @notice Gets user's position contract address from router
     * @param _user User address
     * @return Address of user's position contract
     */
    function _addressPositions(address _user) internal view returns (address) {
        return ILPRouter(router).addressPositions(_user);
    }

    /**
     * @notice Internal function to supply liquidity via router
     * @param _amount Amount to supply
     * @param _user User address
     * @return Shares minted
     */
    function _supplyLiquidity(uint256 _amount, address _user) internal returns (uint256) {
        return ILPRouter(router).supplyLiquidity(_amount, _user);
    }

    /**
     * @notice Internal function to withdraw liquidity via router
     * @param _shares Shares to burn
     * @param _owner Owner whose shares are redeemed
     * @return Amount withdrawn
     */
    function _withdrawLiquidity(uint256 _shares, address _owner) internal returns (uint256) {
        return ILPRouter(router).withdrawLiquidity(_shares, _owner);
    }

    /**
     * @notice Internal function to process borrow request via router
     * @param _amount Amount to borrow
     * @param _user User address
     * @return protocolFee Protocol fee amount
     * @return userAmount Amount user receives
     * @return shares Borrow shares minted
     */
    function _borrowDebt(uint256 _amount, address _user) internal returns (uint256, uint256, uint256, uint256) {
        return ILPRouter(router).borrowDebt(_amount, _user);
    }

    /**
     * @notice Gets factory contract address from router
     * @return Factory address
     */
    function _factory() internal view returns (address) {
        return ILPRouter(router).factory();
    }

    // =============================================================
    //                   FACTORY & PROTOCOL GETTERS
    // =============================================================

    /**
     * @notice Gets protocol address from factory
     * @return Protocol address
     */
    function _protocol() internal view returns (address) {
        return IFactory(_factory()).protocol();
    }

    /**
     * @notice Gets wrapped native token address from factory
     * @return Wrapped native token address
     */
    function _wrappedNative() internal view returns (address) {
        return IFactory(_factory()).wrappedNative();
    }

    /**
     * @notice Gets the owner address from factory
     * @dev Internal view function that queries the factory for the owner address
     * @return The address of the owner
     */
    function _ownerFactory() internal view returns (address) {
        return IFactory(_factory()).owner();
    }

    /**
     * @notice Gets the PaboxoEmitter address from factory
     * @return PaboxoEmitter address
     */
    function _paboxoEmitter() internal view returns (address) {
        return IFactory(_factory()).paboxoEmitter();
    }

    // =============================================================
    //                      TRANSFER HANDLERS
    // =============================================================

    /**
     * @notice Internal function to handle liquidity supply token transfer
     * @param _amount Amount to transfer
     * @dev Handles both native and ERC20 tokens
     */
    function _supplyLiquidityTransfer(uint256 _amount) internal {
        address borrowToken = _borrowToken();
        if (borrowToken == address(1)) {
            if (msg.value != _amount) revert SupplyLiquidityWrongInputAmount(msg.value, _amount);
            IWrappedNative(_wrappedNative()).deposit{ value: _amount }();
        } else {
            IERC20(borrowToken).safeTransferFrom(_msgSender(), address(this), _amount);
        }
    }

    /**
     * @notice Internal function to handle liquidity withdrawal token transfer
     * @param amount Amount to withdraw
     * @param _owner Recipient of the underlying tokens (the share owner)
     * @dev Handles both native and ERC20 tokens, unwraps native tokens
     */
    function _withdrawLiquidityTransfer(uint256 amount, address _owner) internal {
        address borrowToken = _borrowToken();
        if (borrowToken == address(1)) {
            _withdrawing = true;
            IWrappedNative(_wrappedNative()).withdraw(amount);
            (bool sent,) = _owner.call{ value: amount }("");
            if (!sent) revert TransferFailed(amount);
            _withdrawing = false;
        } else {
            IERC20(borrowToken).safeTransfer(_owner, amount);
        }
    }

    /**
     * @notice Internal function to handle collateral supply token transfer
     * @param _user User address
     * @param _amount Amount to supply
     * @dev Transfers tokens from user to their position contract
     */
    function _supplyCollateralTransfer(address _user, uint256 _amount) internal {
        address position = _addressPositions(_user);
        address collateralToken = _collateralToken();
        if (collateralToken == address(1)) {
            if (msg.value != _amount) revert CollateralWrongInputAmount(msg.value, _amount);
            address wrappedNative = _wrappedNative();
            IWrappedNative(wrappedNative).deposit{ value: msg.value }();
            // No approve needed: safeTransfer moves this pool's own wrapped-native balance. A standing
            // allowance to the Position would be a residual confused-deputy foothold, so it is omitted.
            IERC20(wrappedNative).safeTransfer(position, _amount);
        } else {
            // On-behalf: pull from the paying caller, deposit into the beneficiary's Position.
            IERC20(collateralToken).safeTransferFrom(_msgSender(), position, _amount);
        }
    }

    /**
     * @notice Internal function to handle collateral withdrawal token transfer
     * @param _amount Amount to withdraw
     * @param _owner Owner whose position is debited and who receives the collateral
     * @dev Withdraws tokens from the owner's position contract to the owner
     */
