     * @dev Cross-chain routing is reworked to Chainlink CCIP (see Phase 7.1) and stays guarded-off for the MVP
     */
    function ccipRouter() external view returns (address);

    /**
     * @notice Returns the creator fee for a lending pool router
     * @param _lendingPoolRouter The lending pool router address
     * @return The creator fee amount
     */
    function creatorFee(address _lendingPoolRouter) external view returns (uint256);

    /**
     * @notice Sets the Chainlink CCIP destination chain selector for a specific chain ID
     * @param _chainId The blockchain chain ID
     * @param _chainSelector The CCIP destination chain selector corresponding to the chain (0 unmaps it)
     * @dev Cross-chain routing is reworked to Chainlink CCIP (see Phase 7.1) and stays guarded-off for the MVP
     */
    function setChainIdToSelector(uint256 _chainId, uint64 _chainSelector) external;

    /**
     * @notice Sets the Chainlink CCIP router address used for cross-chain borrows
     * @param _ccipRouter Address of the CCIP router (address(0) disables cross-chain)
     * @dev Cross-chain routing is reworked to Chainlink CCIP (see Phase 7.1) and stays guarded-off for the MVP
