pragma solidity ^0.8.20;

import { Client } from "../libraries/Client.sol";

/**
 * @title IRouterClient
 * @dev Chainlink CCIP router entry point used by Paboxo's cross-chain borrow roadmap.
 * @notice Replaces the prior deployment's LayerZero OFT `send()` transport. The destination
 *         network is addressed by a CCIP chain selector (e.g. HashKey mainnet =
 *         7613811247471741961) rather than a LayerZero EID — see
 *         docs/HASHKEY-INTEGRATION.md §Cross-chain (CCIP). Cross-chain borrow stays a documented
 *         roadmap item and is guarded off in the single-chain MVP.
 * @author Paboxo Team
 * @custom:version 1.0.0
 */
interface IRouterClient {
    error UnsupportedDestinationChain(uint64 destChainSelector);
    error InsufficientFeeTokenAmount();
    error InvalidMsgValue();

    /**
     * @notice Checks whether a destination chain selector is supported for CCIP sends.
     * @param destChainSelector The destination chain selector.
     * @return supported True if the router can route to the given chain.
     */
    function isChainSupported(uint64 destChainSelector) external view returns (bool supported);

    /**
     * @notice Quotes the fee for delivering a message to the destination chain.
     * @param destinationChainSelector The destination chain selector.
     * @param message The cross-chain CCIP message including data and/or tokens.
     * @return fee Execution fee denominated in the feeToken specified in the message
     *         (native token if `message.feeToken` is address(0)).
     */
    function getFee(uint64 destinationChainSelector, Client.EVM2AnyMessage memory message) external view returns (uint256 fee);

    /**
     * @notice Sends a cross-chain message (and optional token transfers) via CCIP.
     * @dev If the feeToken is address(0), the fee must be supplied as msg.value.
     * @param destinationChainSelector The destination chain selector.
     * @param message The cross-chain CCIP message including data and/or tokens.
     * @return messageId The unique CCIP message identifier for tracking delivery.
     */
    function ccipSend(uint64 destinationChainSelector, Client.EVM2AnyMessage calldata message) external payable returns (bytes32 messageId);
}

