// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title Client
 * @dev Chainlink CCIP message primitives, vendored for the Paboxo cross-chain roadmap.
 * @notice These are the standard CCIP `Client` structs and helpers consumed by
 *         {IRouterClient}. HashKey Chain's officially referenced cross-chain bridge is
 *         Chainlink CCIP, which replaces the prior deployment's LayerZero OFT path — see
 *         docs/HASHKEY-INTEGRATION.md §Cross-chain (CCIP). Kept byte-compatible with the
 *         upstream Chainlink layout so on-chain routers accept the encoded payload.
 * @author Paboxo Team
 * @custom:version 1.0.0
 */
library Client {
    /// @dev A token and its amount, expressed in the local chain's token representation.
    struct EVMTokenAmount {
        address token; // token address on the local chain.
        uint256 amount; // Amount of tokens.
    }

    /// @dev Inbound message shape delivered to a CCIP receiver on the destination chain.
    struct Any2EVMMessage {
        bytes32 messageId; // MessageId corresponding to ccipSend on source.
        uint64 sourceChainSelector; // Source chain selector.
        bytes sender; // abi.decode(sender) if coming from an EVM chain.
        bytes data; // payload sent in original message.
        EVMTokenAmount[] destTokenAmounts; // Tokens and their amounts in their destination chain representation.
    }

    /// @dev Outbound message shape passed to {IRouterClient-ccipSend}. If extraArgs is empty
    ///      bytes, the router applies a default 200k gas limit on the destination chain.
    struct EVM2AnyMessage {
        bytes receiver; // abi.encode(receiver address) for dest EVM chains.
        bytes data; // Data payload.
        EVMTokenAmount[] tokenAmounts; // Token transfers.
        address feeToken; // Address of feeToken. address(0) means you will send msg.value.
        bytes extraArgs; // Populate this with _argsToBytes(EVMExtraArgsV1 / EVMExtraArgsV2).
    }

    /// @dev bytes4(keccak256("CCIP EVMExtraArgsV1"));
    bytes4 public constant EVM_EXTRA_ARGS_V1_TAG = 0x97a657c9;

    struct EVMExtraArgsV1 {
        uint256 gasLimit;
    }

    /// @dev bytes4(keccak256("CCIP EVMExtraArgsV2"));
    bytes4 public constant EVM_EXTRA_ARGS_V2_TAG = 0x181dcf10;

    /**
     * @param gasLimit Gas limit for the callback on the destination chain.
     * @param allowOutOfOrderExecution If true, the message may be executed in any order relative
     *        to other messages from the same sender.
     */
    struct EVMExtraArgsV2 {
        uint256 gasLimit;
        bool allowOutOfOrderExecution;
    }

    /// @notice Encodes {EVMExtraArgsV1} into the tagged bytes blob CCIP expects in `extraArgs`.
    function _argsToBytes(EVMExtraArgsV1 memory extraArgs) internal pure returns (bytes memory bts) {
        return abi.encodeWithSelector(EVM_EXTRA_ARGS_V1_TAG, extraArgs);
    }

    /// @notice Encodes {EVMExtraArgsV2} into the tagged bytes blob CCIP expects in `extraArgs`.
    function _argsToBytes(EVMExtraArgsV2 memory extraArgs) internal pure returns (bytes memory bts) {
        return abi.encodeWithSelector(EVM_EXTRA_ARGS_V2_TAG, extraArgs);
    }
}
